try { new Function('X', 'applyMacros', "/* 💞 好感两层：TA 对你的感情分成「心里」和「面上」两层——嘴硬的人心里早就软了，面上还是淡淡的。只在聊天里有实打实的证据时才挪一格，每次挪都记下是哪句话；和「关系账本」的分数是两回事，账本记事，这里记心口不一 */\nif (window.__gyxDual) return; window.__gyxDual = 1;\nX.feat('gyxDual', { n: '💞 好感两层', desc: '心里怎么想、面上怎么表现分开记，有证据才挪，心口不一会自然流露' });\nconst S = X.store('dual');\nconst IN = ['强烈反感', '反感', '提防', '没感觉', '有点在意', '喜欢', '很喜欢', '感情深厚'];\nconst OUT = ['明显敌对', '冷淡', '客气疏离', '正常', '友好', '亲近', '明显亲近'];\nlet D = { st: {}, cfg: { every: 20, show: true } };   // st[cid] = {i, o, log:[{id, at, layer, from, to, ev}], seen}\nconst stOf = cid => (D.st[String(cid)] = D.st[String(cid)] || { i: 5, o: 4, log: [], seen: null });\nconst msgsOf = cid => ((typeof globalChats !== 'undefined' && globalChats[cid]) || []).filter(m => m && m.sender !== 'system' && !m.side);\nconst clamp = (v, L) => Math.max(0, Math.min(L.length - 1, v | 0));\nfunction move(cid, layer, to, ev, src) {\n    const s = stOf(cid), L = layer === 'i' ? IN : OUT, from = s[layer]; to = clamp(to, L);\n    if (to === from) return null;\n    s[layer] = to; const it = { id: 'du' + Date.now().toString(36) + Math.random().toString(36).slice(2, 4), at: Date.now(), layer, from, to, ev: String(ev || '').slice(0, 80), src: src || 'chat' };\n    s.log.unshift(it); return it;\n}\nasync function judge(c, force) {\n    const cid = String(c.id), all = msgsOf(cid), s = stOf(cid);\n    const fresh = all.slice(force ? Math.max(0, all.length - 40) : (s.seen || 0)); s.seen = all.length; await S.set('d', D);\n    if (X.bailu() || fresh.length < 4) return 0;\n    const rel = window.gyRel ? `（关系账本里现在是「${(st => typeof st === 'string' ? st : ((st || {}).name || ''))(window.gyRel.stage(cid))}」，仅供参考）` : '';\n    const chat = fresh.slice(-50).map(m => (m.sender === 'me' ? '她：' : '你：') + X.plain(m.text).slice(0, 160)).join('\\n');\n    const j = X.json(await X.ask(`${X.who(c)}\\n分两层看你对她的感情：\\n心里（真实感受）现在是「${IN[s.i]}」，可选：${IN.join(' / ')}\\n面上（表现出来的）现在是「${OUT[s.o]}」，可选：${OUT.join(' / ')}\\n${rel}\\n\\n最近的聊天：\\n${chat}\\n\\n规则：没有实打实的证据就不动；一次最多挪一格；心里和面上可以不一样（嘴硬、害羞、端着、装没事）。动了的话 ev 写聊天里的那句话或那件事。\\n只输出 JSON：{\"inner\":\"不变 或 新档位\",\"innerEv\":\"\",\"outer\":\"不变 或 新档位\",\"outerEv\":\"\"}`));\n    if (!j) return 0; let n = 0;\n    const st = (k, L, ev, layer) => { const v = L.indexOf(String(j[k] || '')); if (v >= 0 && ev && Math.abs(v - s[layer]) >= 1) { if (move(cid, layer, s[layer] + Math.sign(v - s[layer]), ev, 'auto')) n++; } };\n    st('inner', IN, j.innerEv, 'i'); st('outer', OUT, j.outerEv, 'o');\n    await S.set('d', D); return n;\n}\nasync function tick() { if (!X.on('gyxDual')) return; for (const c of X.chars()) { const s = stOf(c.id), n = msgsOf(c.id).length; if (s.seen == null) { s.seen = n; continue; } if (n - s.seen >= Math.max(6, +D.cfg.every || 20)) await judge(c); } await S.set('d', D); }\nwindow.gyxDualJudge = async cid => { const c = X.char(cid) || X.cur(); if (!c) return 0; const n = await judge(c, true); window.gyxDualOpen(c.id); return n; };\nwindow.gyxDualSet = async (cid, layer, v, ev) => { move(cid, layer, +v, ev || '你手动调的', 'me'); await S.set('d', D); window.gyxDualOpen(cid); };\nwindow.gyxDualDel = async (cid, id) => { const s = stOf(cid), i = s.log.findIndex(x => x.id === id); if (i >= 0) s.log.splice(i, 1); await S.set('d', D); window.gyxDualOpen(cid); };\nwindow.gyxDualCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nwindow.gyxDualData = () => D;\nconst gap = s => s.i - Math.round(s.o * (IN.length - 1) / (OUT.length - 1));\nwindow.gyxDualOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), s = stOf(cid), g = gap(s);\n    const bar = (L, v, layer) => `<div class=\"du-bar\">${L.map((n, k) => `<i class=\"${k === v ? 'on' : ''}\" onclick=\"gyxDualSet('${cid}','${layer}',${k})\">${n}</i>`).join('')}</div>`;\n    X.panel('gyxDualOv', '💞 好感两层', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxDualOpen')}${X.bailu() ? '' : `<button class=\"gyx-btn lite\" onclick=\"this.disabled=true;this.textContent='在看…';gyxDualJudge('${cid}')\">看看最近有没有变</button>`}</div>\n        <div class=\"du-h\">💗 心里</div>${bar(IN, s.i, 'i')}<div class=\"du-h\">🙂 面上</div>${bar(OUT, s.o, 'o')}\n        <div class=\"gyx-card gyx-tip\">${g >= 2 ? X.v('嘴上淡淡的，心里早就软了。', '面上端着，心里藏不住。', '装作没什么，其实很在意。') : g <= -2 ? X.v('面上热络，心里还隔着一层。', '客客气气的好，心里还没真放进去。') : X.v('心里和面上差不多，挺坦诚的。', '想什么就表现成什么样。')}</div>\n        <div class=\"du-h\">为什么挪的</div>${s.log.slice(0, 40).map(x => `<div class=\"du-it\"><span>${x.layer === 'i' ? '心里' : '面上'} ${X.esc((x.layer === 'i' ? IN : OUT)[x.from])} → <b>${X.esc((x.layer === 'i' ? IN : OUT)[x.to])}</b></span><em>${X.esc(x.ev)} · ${new Date(x.at).toLocaleDateString()}</em><i onclick=\"gyxDualDel('${cid}','${x.id}')\">删</i></div>`).join('') || '<div class=\"gyx-tip\">还没挪过</div>'}\n        <div class=\"gyx-row gyx-tip\">每聊 <input class=\"gyx-who\" type=\"number\" min=\"6\" value=\"${D.cfg.every}\" style=\"width:60px\" onchange=\"gyxDualCfg('every',+this.value)\"> 句看一次 · <label><input type=\"checkbox\" ${D.cfg.show ? 'checked' : ''} onchange=\"gyxDualCfg('show',this.checked)\"> 告诉 TA 自己现在是哪一档</label></div>\n        <div class=\"gyx-tip\">${X.bailu() ? '白露没接 API：点上面的档位手动挪。' : '只在有证据时挪一格，点档位也能手动改。'}</div>`);\n};\nX.ctx(id => { if (!D.cfg.show) return ''; const s = D.st[String(id)]; if (!s) return ''; const g = gap(s); return `【你对她的感情（两层）】心里：${IN[s.i]}；面上：${OUT[s.o]}。${g >= 2 ? '心里比面上在意得多——按面上的样子说话，但小细节里藏不住。' : g <= -2 ? '面上比心里热络——客气归客气，别装得太过。' : ''}`; }, 'gyxDual');\nX.action({ key: 'gyx_dual', label: '一不小心流露一句心里话', hint: '面上淡淡的，心里早就软了', need: c => { const s = D.st[String(c.id)]; return !!s && gap(s) >= 2; },\n    run: async c => (await X.reach(c, '你面上一直端着，心里其实很在意她。这次不小心流露一点点真心（说完可能还想找补一下）')) ? '不小心说了句心里话' : null }, 'gyxDual');\nX.today(() => { const rows = []; X.chars().forEach(c => { const s = D.st[String(c.id)]; if (!s) return; s.log.filter(x => X.day(new Date(x.at)) === X.day()).forEach(x => rows.push({ t: x.layer === 'i' ? '心里' : '面上', x: `${X.esc(X.name(c))}：${X.esc((x.layer === 'i' ? IN : OUT)[x.to])}`, go: `gyxDualOpen('${c.id}')` })); }); return { title: '💞 好感两层', rows }; }, 'gyxDual');\nX.widget('gyxDualW', { n: '好感两层', sizes: ['s', 'm'], tap: () => window.gyxDualOpen(), r: w => { const c = X.cur(); if (!c) return X.gw(w, '💞', '好感两层', []); const s = stOf(c.id); return X.gw(w, '💞', X.name(c), ['心里 ' + IN[s.i], '面上 ' + OUT[s.o]]); } }, 'gyxDual');\nX.mem({ k: 'gyxDual', ico: '💞', n: '好感两层', d: '心里/面上每一次挪动和证据', items: c => stOf(c.id).log, text: x => x.ev, edit: (x, v) => { x.ev = v; }, del: (c, i) => { stOf(c.id).log.splice(i, 1); }, meta: x => (x.layer === 'i' ? '心里 ' + IN[x.to] : '面上 ' + OUT[x.to]) + ' · ' + new Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxDual');\nX.css('gyxDualCss', `.du-h{font-weight:700;margin:12px 0 6px;font-size:14px}.du-bar{display:flex;flex-wrap:wrap;gap:4px}.du-bar i{font-style:normal;font-size:12px;padding:5px 9px;border-radius:10px;background:#f2f2f4;cursor:pointer}.du-bar i.on{background:linear-gradient(135deg,#ff8fb1,#c86bff);color:#fff}.du-it{display:flex;flex-direction:column;padding:7px 2px;border-bottom:1px solid #f3f3f3;font-size:13.5px;position:relative}.du-it em{font-style:normal;font-size:12px;color:#888}.du-it i{position:absolute;right:2px;top:8px;font-style:normal;font-size:11px;color:#aaa;cursor:pointer}`);\nX.mini({ id: 'gyxDual', icon: '💞', title: '好感两层', desc: '心里怎么想、面上怎么表现，分开记', cat: '回忆', onOpen: () => window.gyxDualOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.st = D.st || {}; D.cfg = Object.assign({ every: 20, show: true }, D.cfg || {}); setTimeout(tick, 25000); setInterval(tick, 60000); })();\n\n//# sourceURL=gyx-plugin/好感两层.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 💞 好感两层 出错：', e); }
/* ==== 📈 我们的等级 ==== */
try { new Function('X', 'applyMacros', "/* 📈 我们的等级：你们一起做的每件事都会涨经验——聊天、散步、合照、哄好 TA、答每日一问、通关寻宝……攒够了就升级、解锁新称号，每升 5 级 TA 还会送一份礼物。经验从哪来的一项项都列着 */\nif (window.__gyxLevel) return; window.__gyxLevel = 1;\nX.feat('gyxLevel', { n: '📈 我们的等级', desc: '一起做的每件事都涨经验，升级解锁称号和礼物，把所有玩法串起来' });\nconst S = X.store('level');\nlet D = { lv: {}, log: [], cust: {} };   // cust[cid]：你（或 TA）改过的称号、经验权重、升级快慢、礼物   // lv[cid] = 上次看到的等级；log = [{cid, lv, at, title, gift}]\nconst TITLES0 = [[1, '刚认识'], [3, '有点熟了'], [5, '聊得来'], [8, '偷偷心动'], [12, '暧昧期'], [16, '正式交往'], [20, '甜蜜期'], [25, '形影不离'], [30, '老夫老妻预备役'], [36, '灵魂伴侣'], [42, '命中注定'], [50, '宇宙级恋人'], [60, '传说中的那一对']];\n// ✏️ 自定义（每个 TA 一套）：称号、每样事情值多少经验（也能关掉）、升级快慢、几级送一次礼物、礼物有哪些、自己加的经验来源（某句话说一次加多少）\nconst GIFTS0 = ['抱抱券', '任性一次券', '陪聊到天亮券', '撒娇券', '免罚券'];\nconst CURVES = { fast: ['快', 60, 25], normal: ['正常', 100, 40], slow: ['慢', 150, 60] };\nconst custOf = cid => { const C = (D.cust[String(cid)] = D.cust[String(cid)] || {}); C.w = C.w || {}; C.off = C.off || {}; C.extra = C.extra || []; return C; };\nconst TITLES = cid => { const t = cid != null && custOf(cid).titles; return Array.isArray(t) && t.length ? t.slice().sort((a, b) => a[0] - b[0]) : TITLES0; };\nconst titleOf = (lv, cid) => { const L = TITLES(cid).filter(t => lv >= t[0]); return (L.pop() || TITLES(cid)[0] || [1, ''])[1]; };\nconst need = (lv, cid) => { const k = CURVES[cid != null && custOf(cid).curve] || CURVES.normal; return k[1] + k[2] * (lv - 1); };   // 从 lv 升到 lv+1 要多少经验\nfunction levelOf(exp, cid) { let lv = 1, left = exp; while (left >= need(lv, cid)) { left -= need(lv, cid); lv++; } return { lv, cur: left, next: need(lv, cid) }; }\nconst giftEvery = cid => Math.max(1, +custOf(cid).every || 5), giftsOf = cid => { const g = custOf(cid).gifts; return Array.isArray(g) && g.length ? g : GIFTS0; };\nconst g = (f, d) => { try { const v = f(); return isFinite(v) ? v : d; } catch (e) { return d; } };\nfunction sources(c) {\n    const cid = String(c.id), L = ((typeof globalChats !== 'undefined' && globalChats[cid]) || []).filter(m => m && m.sender !== 'system' && !m.side), days = new Set(L.filter(m => m.timestamp).map(m => X.day(new Date(m.timestamp)))).size;\n    const arr = (f) => g(() => f().length, 0);\n    return [\n        ['💬', '说过的话', L.length, 1], ['📅', '聊天的天数', days, 15],\n        ['🚶', '一起散步（公里）', g(() => window.gyxWalkData().walks.filter(x => x.cid === cid).reduce((a, x) => a + x.dist, 0) / 1000, 0), 20], ['📸', '合照', arr(() => window.gyxDuoData().pics.filter(x => x.cid === cid)), 30],\n        ['🥺', '哄好 TA', arr(() => window.gyxCoaxData().log.filter(x => x.cid === cid)), 60], ['🤙', '吵架又和好', arr(() => window.gyxMakeupData().log.filter(x => x.cid === cid)), 60],\n        ['🤞', '做到的约定', arr(() => window.gyxPromiseData().list.filter(x => x.cid === cid && x.done === true)), 20], ['💞', '答对的默契题', arr(() => window.gyxQuizData().log.filter(x => x.cid === cid && x.ok)), 10],\n        ['🌅', '每日一问', g(() => Object.values(window.gyxDailyData().days[cid] || {}).filter(x => x.me).length, 0), 15], ['🕯️', '睡前三件好事', g(() => Object.values(window.gyxGoodData().days[cid] || {}).filter(x => x.me).length, 0), 15],\n        ['🗺️', '通关寻宝', arr(() => window.gyxHuntData().log.filter(x => x.cid === cid)), 100], ['🧭', '打通冒险', arr(() => window.gyxQuestData().log.filter(x => x.cid === cid)), 80],\n        ['🏃', '一起运动', arr(() => window.gyxCoachData().log.filter(x => x.cid === cid)), 25], ['🎵', 'TA 写的歌', arr(() => window.gyxSongData().list.filter(x => x.cid === cid)), 50],\n        ['🧾', '审批单', arr(() => window.gyxOAData().list.filter(x => x.cid === cid && x.res)), 10],\n        ['📋', '问卷', arr(() => window.gyxSurveyData().res.filter(x => x.cid === cid)), 20], ['🎟️', '兑换过的券', arr(() => window.gyxCouponData().list.filter(x => x.cid === cid && x.used)), 15],\n        ['🏅', '解锁的成就', g(() => Object.keys(window.gyxBadgeData().got[cid] || {}).length, 0), 40], ['🍁', '捡到的小东西', g(() => Object.values(window.gyxDropData().got[cid] || {}).reduce((a, x) => a + x.n, 0), 0), 5],\n        ['🎨', '表情包', arr(() => window.gyxMemeData().list.filter(x => x.cid === cid)), 10], ['📼', '磁带', g(() => window.gyxTapeData ? window.gyxTapeData().tapes.filter(x => x.cid === cid).length : 0, 0), 20]\n    ].concat(custOf(cid).extra.map(x => { const re = (() => { const L = String(x.kw || '').split(/[|｜/、,，]/).map(t => t.trim()).filter(Boolean).map(t => t.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')); return new RegExp(L.length ? L.join('|') : '(?!)'); })(); return [x.ico || '✨', x.n || ('说「' + x.kw + '」'), L.filter(m => (x.who === 'me' ? m.sender === 'me' : x.who === 'ta' ? m.sender !== 'me' : true) && re.test(X.plain(m.text))).length, +x.w || 1, x.id]; }))\n     .map(([ico, n, v, w, id]) => { const C = custOf(cid), ww = id ? w : (C.w[n] != null ? +C.w[n] : w); return { ico, n, v: Math.floor(v * 10) / 10, w: ww, w0: w, id, off: !id && !!C.off[n], exp: !id && C.off[n] ? 0 : Math.floor(v * ww) }; });\n}\nconst expOf = c => sources(c).reduce((a, s) => a + s.exp, 0);\nasync function check(c, quiet) {\n    const cid = String(c.id), L = levelOf(expOf(c), cid), was = D.lv[cid];\n    if (was == null || quiet) { D.lv[cid] = L.lv; await S.set('d', D); return null; }\n    if (L.lv <= was) return null;\n    D.lv[cid] = L.lv; const title = titleOf(L.lv, cid), titleNew = titleOf(was, cid) !== title, gift = Math.floor(L.lv / giftEvery(cid)) > Math.floor(was / giftEvery(cid));\n    let giftName = '';\n    if (gift) { giftName = X.pick(giftsOf(cid)); try { window.gyxCouponData().list.unshift({ id: 'cp' + Date.now().toString(36), cid, from: 'ta', name: giftName, desc: `Lv.${L.lv} 的升级礼物`, at: Date.now(), used: null }); } catch (e) { giftName = ''; } }\n    D.log.unshift({ cid, lv: L.lv, from: was, at: Date.now(), title: titleNew ? title : '', gift: giftName }); await S.set('d', D);\n    X.notify(c, `📈 ${X.v('升级啦', '叮——等级提升', '你们又近了一点')}：Lv.${L.lv}${titleNew ? ' · 「' + title + '」' : ''}`, giftName ? `TA 送了你一张「${giftName}」` : '和 ' + X.name(c), () => window.gyxLevelOpen(cid));\n    return D.log[0];\n}\nasync function tick() { if (!X.on('gyxLevel')) return; for (const c of X.chars()) await check(c); }\nwindow.gyxLevelCheck = async cid => { const c = X.char(cid) || X.cur(); return check(c); };\nwindow.gyxLevelData = () => D;\nwindow.gyxLevelInfo = cid => { const c = X.char(cid) || X.cur(); const e = expOf(c), L = levelOf(e, c.id); return Object.assign({ exp: e, title: titleOf(L.lv, c.id) }, L); };\nlet TAB = 'lv';\nwindow.gyxLevelTab = (cid, t) => { TAB = t; window.gyxLevelOpen(cid); };\nwindow.gyxLevelOpen = function (who) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), S2 = sources(c), e = S2.reduce((a, s) => a + s.exp, 0), L = levelOf(e, cid), pct = Math.round(L.cur / L.next * 100), ge = giftEvery(cid);\n    const tabs = `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxLevelOpen')}<span class=\"gyx-chip${TAB === 'lv' ? ' on' : ''}\" onclick=\"gyxLevelTab('${cid}','lv')\">等级</span><span class=\"gyx-chip${TAB === 'edit' ? ' on' : ''}\" onclick=\"gyxLevelTab('${cid}','edit')\">✏️ 自定义</span></div>`;\n    if (TAB === 'edit') return X.panel('gyxLvOv', '📈 我们的等级', tabs + editHtml(c, S2));\n    X.panel('gyxLvOv', '📈 我们的等级', `${tabs}\n        <div class=\"lv-hero\"><div class=\"lv-ring\" style=\"--p:${pct}\"><b>Lv.${L.lv}</b></div><div><div class=\"lv-t\">「${X.esc(titleOf(L.lv, cid))}」</div><div class=\"gyx-tip\">${X.esc(X.name(c))} & ${X.esc(X.me(c))} · 总经验 ${e}</div><div class=\"lv-bar\"><i style=\"width:${pct}%\"></i></div><div class=\"gyx-tip\">再 ${L.next - L.cur} 经验升到 Lv.${L.lv + 1}${Math.floor((L.lv + 1) / ge) > Math.floor(L.lv / ge) ? ' · 🎁 有礼物' : ''}</div></div></div>\n        <div class=\"lv-h\">经验从哪来</div><div class=\"lv-src\">${S2.filter(s => s.v > 0 && !s.off).sort((a, b) => b.exp - a.exp).map(s => `<div><span>${X.esc(s.ico)} ${X.esc(s.n)}</span><em>${s.v} × ${s.w}</em><b>+${s.exp}</b></div>`).join('') || '<div class=\"gyx-tip\">一起做点什么吧</div>'}</div>\n        <div class=\"lv-h\">称号${custOf(cid).by === 'ta' ? `<span c