Date(x.at).toLocaleDateString(), save: () => S.set('d', D) }, 'gyxLevel');\nX.mem({ k: 'gyxLevelTitles', ico: '🏷️', n: '我们的等级·称号', d: '这个 TA 的称号（改了就是改这一级叫什么）', items: c => TITLES(c.id).map((t, i) => ({ i, t, cid: String(c.id) })), text: x => 'Lv.' + x.t[0] + ' ' + x.t[1], edit: (x, v) => { const C = custOf(x.cid); C.titles = TITLES(x.cid).map(y => y.slice()); C.titles[x.i][1] = String(v).replace(/^Lv\\.\\d+\\s*/, '').slice(0, 16); }, del: (c, i) => { const C = custOf(c.id); C.titles = TITLES(c.id).map(y => y.slice()); if (C.titles.length > 1) C.titles.splice(i, 1); }, meta: x => custOf(x.cid).by === 'ta' ? 'TA 起的' : custOf(x.cid).titles ? '你改过' : '默认', save: () => S.set('d', D) }, 'gyxLevel');\nX.css('gyxLvCss', `.lv-er{margin:4px 0}.lv-er select,.lv-er input{min-width:0;max-width:100%}.lv-x{font-style:normal;font-size:12px;color:#c33;cursor:pointer;padding:4px 6px}.lv-w input{justify-self:end}.lv-w>div{grid-template-columns:1fr auto auto!important}.lv-hero{display:flex;gap:16px;align-items:center;padding:12px;border-radius:20px;background:linear-gradient(135deg,#fff3e6,#ffe9f2)}.lv-ring{width:96px;height:96px;flex:none;border-radius:50%;background:conic-gradient(#ff7aa2 calc(var(--p)*1%),#f1e4e9 0);display:flex;align-items:center;justify-content:center;position:relative}.lv-ring:before{content:'';position:absolute;inset:9px;border-radius:50%;background:#fff8f3}.lv-ring b{position:relative;font-size:22px;color:#d0456f}.lv-t{font-size:20px;font-weight:800;color:#a63c5c}.lv-bar{height:8px;border-radius:6px;background:#f3dfe6;overflow:hidden;margin:6px 0 2px}.lv-bar i{display:block;height:100%;background:linear-gradient(90deg,#ffb37a,#ff7aa2)}.lv-h{font-weight:700;margin:14px 0 6px}.lv-src>div{display:flex;gap:8px;align-items:baseline;padding:5px 2px;border-bottom:1px dashed #eee;font-size:13.5px}.lv-src span{flex:1}.lv-src em{font-style:normal;font-size:11.5px;color:#aaa}.lv-src b{color:#d0456f;min-width:52px;text-align:right}.lv-tt{display:flex;flex-wrap:wrap;gap:6px